    const timer=setTimeout(()=>{finish();reject(new Error('Source timed out'));},15000);
    script.onload=()=>{finish();if(!cache.has(path))reject(new Error('Incomplete source'));};
    script.onerror=()=>{finish();reject(new Error('Source unavailable'));};
